package ekpol

import (
	"github.com/nick-fedchik/kuzmin-machine/Engineering/sw/kpol-go/kpol"
)

// The cross-check required by EKPOL-B64-20 runs the KPOL text generated by the
// EKPOL translator through the profile compilers of package kpol
// (compile_concept_microcode_bram_image with profile KPOL-CME-1 / KPOL-CME-2).
// The security ACL audit is vacuous here: the translator emits Int32 states only.

// compileCME1 is compile_concept_microcode_bram_image(module, profile="KPOL-CME-1").
func compileCME1(m *kpol.Module) ([]byte, error) {
	return kpol.CompileProfile(m, kpol.ProfileCME1)
}

// compileCME2 is compile_concept_microcode_bram_image(module, profile="KPOL-CME-2").
func compileCME2(m *kpol.Module) ([]byte, error) {
	return kpol.CompileProfile(m, kpol.ProfileCME2)
}
